      "title": "The Sadistic Ultimatum",
      "start_block": "B032",
      "end_block": "B045",
      "hook": "Clarissa demands Juliana retrieve a ring from razor-sharp frozen briars with bare hands.",
      "cliffhanger": "Clarissa whispers that if Juliana refuses, her husband will hang from the gallows.",
      "why": "Combines immediate physical danger with an impossible choice and a death threat in under 15 seconds.",
      "context_gap": "None; the stakes (life vs. torture) are clear immediately."
    },
    {
      "title": "Defiance Against the Gallows",
      "start_block": "B046",
      "end_block": "B055",
      "hook": "Alexander begs Juliana not to hurt herself while she grips her dress in agony.",
      "cliffhanger": "Juliana turns sharply and demands to know where the garden is, freezing on her defiant stare.",
      "why": "Shows the emotional peak of sacrifice followed by a decisive action that leaves the outcome unknown.",
      "context_gap": "None; the viewer sees her choose to save him despite the risk."
    },
    {
      "title": "Planted Evidence Revealed",
      "start_block": "B010",
      "end_block": "B028",
      "hook": "Gerald smugly claims the watch was found in Alexander's coat, calling him a beggar.",
      "cliffhanger": "Clarissa purrs that she wants to see Juliana crawl, hinting at a cruel game.",
      "why": "Establishes the villainy and the false accusation quickly, ending on the promise of sadistic revenge.",
      "context_gap": "A stranger might not know the watch was planted, but understands it's a setup against the couple."
    }
  ],
  "moments": [
    {
      "start_block": "B002",
      "end_block": "B007",
      "kind": "hook",
      "description": "Constable arrests Alexander for theft, claiming he found the watch in his coat."
    },
    {
      "start_block": "B020",
      "end_block": "B024",
      "kind": "emotional",
      "description": "Alexander clenches his fist in fury while Juliana demands Clarissa name her price."
    },
    {
      "start_block": "B039",
      "end_block": "B041",
      "kind": "reveal",
      "description": "Clarissa reveals the briars are sharp as steel and frozen like ice, mocking the lady's hands."
    },
    {
      "start_block": "B045",
      "end_block": "B045",
      "kind": "cliffhanger",
      "description": "Clarissa whispers the ultimatum: fail and your husband hangs."
    }
  ]
}
